// judgment_flow.go は review-triage の判定フローの正本 (judgment-flow.md) を検査し、
// 図を生成する (judgment-flow)。
//
// 正本の分担は次のとおり。決定表 (ID / 種類 / 表示名 / 条件・内容 / 記録に書くもの) が
// ノードの正本、遷移表 (始点 / 条件 / 遷移先) が遷移の正本で、mermaid の図はこの 2 つの
// 表から生成する生成物 (手で編集しない)。
//
// 以前は手描きの図が遷移の正本で、検査は mermaid の行を正規表現で読んでいた。
// 遷移を構造化して持つ場所が無いため、遷移の書き忘れは目で見るしかなく、
// 検査は記法の揺れに弱く、遷移先や決着ノードの規則を見るには正規表現を継ぎ足す
// しかなかった (同じ型の指摘が 2 回続いた)。表を正本にすれば、ノードの種類ごとの
// 規則は表の上で確かめられ、図は生成し直した結果との一致 (鮮度) で守れる —
// 記録 YAML と生成サマリの関係と同じ。
package main

import (
	"errors"
	"fmt"
	"io/fs"
	"os"
	"regexp"
	"sort"
	"strings"
)

// judgmentFlowPath は判定フローの正本。ファイルが存在しないときは検査を
// 何もしない (対象は git 追跡でなくファイルの実在で決める)。
//
// スキルがプラグインとして配られると、この正本はリポジトリの外 (プラグインの
// 展開先) に置かれ、パスは環境ごとに違う。main が CLAUDE_PLUGIN_ROOT または
// -judgment-flow から解決して設定する。既定はリポジトリ内にスキルを直接置く
// 形 (プラグイン化前の配置) で、そのときだけこの値がそのまま使われる。
var judgmentFlowPath = ".claude/skills/review-triage/references/judgment-flow.md"

// judgmentFlowRegenerateHint は図の再生成手段として案内する文字列。判定フローは
// プラグインの開発者だけが編集するので、記録のサマリ (-summary-command) のように
// 利用側から渡す仕組みは持たない。
const judgmentFlowRegenerateHint = "triagecheck -write-judgment-flow"

var (
	// judgmentFlowIDRe はノード ID の形。判定 (D)・評価 (E)・採択 (A)・保留 (H)・
	// 却下 (R) の種別と番号。
	judgmentFlowIDRe = regexp.MustCompile(`^([ADEHR])\d+$`)
	// judgmentFlowSeparatorRe は表の区切り行 (| --- | --- |)。直前の行は見出し。
	judgmentFlowSeparatorRe = regexp.MustCompile(`^\s*\|(\s*:?-{3,}:?\s*\|)+\s*$`)
)

// judgmentFlowKindOf は ID の先頭文字から種類を返す。決定表の「種類」の列と
// 照合し、片方だけ直した不整合を報告するために使う。
var judgmentFlowKindOf = map[string]string{"D": "判定", "E": "評価", "A": "決着", "H": "決着", "R": "決着"}

// judgmentFlowStyle は種類ごとの図の色。採択は緑、保留は琥珀、却下は赤、評価は藍。
// 判定は既定のまま。
var judgmentFlowStyle = map[string]string{
	"A": "fill:#16a34a2e,stroke:#16803c,stroke-width:2px",
	"H": "fill:#f59e0b2e,stroke:#b45309",
	"R": "fill:#dc26262e,stroke:#b91c1c",
	"E": "fill:#6366f12e,stroke:#4f46e5",
}

// judgmentFlowNode は決定表の 1 行。Label は図に出す表示名。
type judgmentFlowNode struct {
	ID    string
	Kind  string
	Label string
	Line  int
}

// judgmentFlowTransition は遷移表の 1 行。Cond は図の辺のラベルで、空なら
// ラベル無しの辺 (評価から次へ進む遷移など)。
type judgmentFlowTransition struct {
	From string
	Cond string
	To   string
	Line int
}

// judgmentFlowDoc は judgment-flow.md を読んだ結果。Diagram は最初の mermaid の
// フェンスの中身 (フェンス自体は含まない)。DiagramStart / DiagramEnd はフェンスの
// 行の添字 (0 始まり) で、図の書き出しに使う。
type judgmentFlowDoc struct {
	Nodes        []judgmentFlowNode
	Transitions  []judgmentFlowTransition
	Diagram      string
	HasDiagram   bool
	DiagramStart int
	DiagramEnd   int
	lines        []string
}

// parseJudgmentFlow は Markdown の判定フローを読む。表の見分けは見出し行の
// 先頭セルで行う — 「ID」なら決定表、「始点」なら遷移表。それ以外の表は読まない。
// 見出しの直後の区切り行から、次に表でない行が来るまでを本体とする。
func parseJudgmentFlow(data []byte) judgmentFlowDoc {
	var doc judgmentFlowDoc
	doc.lines = strings.Split(string(data), "\n")
	doc.DiagramStart, doc.DiagramEnd = -1, -1
	inMermaid := false
	var diagram []string
	table := "" // 読んでいる表の種類 ("ID" / "始点" / "")
	for i, line := range doc.lines {
		trimmed := strings.TrimSpace(line)
		if inMermaid {
			if strings.HasPrefix(trimmed, "```") {
				inMermaid = false
				doc.DiagramEnd = i
				doc.Diagram = strings.Join(diagram, "\n")
				continue
			}
			diagram = append(diagram, line)
			continue
		}
		if strings.HasPrefix(trimmed, "```mermaid") && !doc.HasDiagram {
			inMermaid = true
			doc.HasDiagram = true
			doc.DiagramStart = i
			continue
		}
		if !strings.HasPrefix(trimmed, "|") {
			table = ""
			continue
		}
		if judgmentFlowSeparatorRe.MatchString(line) {
			continue
		}
		cells := judgmentFlowCells(line)
		if i+1 < len(doc.lines) && judgmentFlowSeparatorRe.MatchString(doc.lines[i+1]) {
			// 見出し行。先頭セルで表の種類を決める。
			if len(cells) > 0 && (cells[0] == "ID" || cells[0] == "始点") {
				table = cells[0]
			} else {
				table = ""
			}
			continue
		}
		switch table {
		case "ID":
			n := judgmentFlowNode{Line: i + 1}
			if len(cells) > 0 {
				n.ID = cells[0]
			}
			if len(cells) > 1 {
				n.Kind = cells[1]
			}
			if len(cells) > 2 {
				n.Label = cells[2]
			}
			doc.Nodes = append(doc.Nodes, n)
		case "始点":
			tr := judgmentFlowTransition{Line: i + 1}
			if len(cells) > 0 {
				tr.From = cells[0]
			}
			if len(cells) > 1 {
				tr.Cond = cells[1]
			}
			if len(cells) > 2 {
				tr.To = cells[2]
			}
			doc.Transitions = append(doc.Transitions, tr)
		}
	}
	return doc
}

// judgmentFlowCells は表の行をセルに分ける。前後のパイプを落とし、各セルの
// 空白を詰める。
func judgmentFlowCells(line string) []string {
	s := strings.TrimSpace(line)
	s = strings.TrimPrefix(s, "|")
	s = strings.TrimSuffix(s, "|")
	parts := strings.Split(s, "|")
	for i := range parts {
		parts[i] = strings.TrimSpace(parts[i])
	}
	return parts
}

// renderJudgmentFlowDiagram は決定表と遷移表から mermaid の図を組み立てる。
// ノードは決定表の順、遷移は遷移表の順、色は種類ごと (採択・保留・却下・評価の順) に
// 出す。判定は菱形、それ以外は角丸でない箱。
func renderJudgmentFlowDiagram(doc *judgmentFlowDoc) string {
	var b strings.Builder
	b.WriteString("flowchart TD\n")
	for _, n := range doc.Nodes {
		label := fmt.Sprintf("%s: %s", n.ID, n.Label)
		if strings.HasPrefix(n.ID, "D") {
			fmt.Fprintf(&b, "  %s{%q}\n", n.ID, label)
		} else {
			fmt.Fprintf(&b, "  %s[%q]\n", n.ID, label)
		}
	}
	b.WriteString("\n")
	for _, tr := range doc.Transitions {
		if tr.Cond == "" {
			fmt.Fprintf(&b, "  %s --> %s\n", tr.From, tr.To)
		} else {
			fmt.Fprintf(&b, "  %s -- %s --> %s\n", tr.From, tr.Cond, tr.To)
		}
	}
	b.WriteString("\n")
	for _, kind := range []string{"A", "H", "R", "E"} {
		for _, n := range doc.Nodes {
			if strings.HasPrefix(n.ID, kind) {
				fmt.Fprintf(&b, "  style %s %s\n", n.ID, judgmentFlowStyle[kind])
			}
		}
	}
	return strings.TrimSuffix(b.String(), "\n")
}

// judgmentFlowProblems は判定フローの正本を検査する。検査は (1) 図と 2 つの表が
// あるか、(2) 決定表 (ID の形・重複・種類と ID の整合・表示名)、(3) 遷移表 (始点と
// 遷移先の実在・重複)、(4) ノードの種類ごとの遷移の規則と到達可能性、(5) 図の鮮度
// (表から生成し直した結果と一致するか)。表に問題がある間は鮮度を比べない
// (直せば両方直る — 記録のサマリと同じ扱い)。
//
// ファイルが無いとき、在り処の指定 (origin) が無ければ未導入として通し、
// 指定があれば報告する (検査が行われないまま緑になるのを避ける)。
// files は他の検査とシグネチャを揃えるための引数で、使わない。
func judgmentFlowProblems(_ []string, readFile func(string) ([]byte, error), origin string) []string {
	data, err := readFile(judgmentFlowPath)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			if origin != "" {
				return []string{fmt.Sprintf(
					"%s: %s が指す判定フローの正本が存在しません (検査が行われないまま緑になるため報告する)",
					judgmentFlowPath, origin)}
			}
			return nil
		}
		return []string{fmt.Sprintf("%s: 読み込みに失敗しました: %v", judgmentFlowPath, err)}
	}
	doc := parseJudgmentFlow(data)
	problems := judgmentFlowTableProblems(&doc)
	if !doc.HasDiagram {
		problems = append(problems, fmt.Sprintf("%s: mermaid の図が見つかりません (表から `%s` で生成する)", judgmentFlowPath, judgmentFlowRegenerateHint))
	}
	if len(problems) > 0 {
		sort.Strings(problems)
		return problems
	}
	if want := renderJudgmentFlowDiagram(&doc); doc.Diagram != want {
		problems = append(problems, fmt.Sprintf(
			"%s: 図が正本 (決定表・遷移表) と食い違っています (`%s` で再生成する。図は手で編集しない)",
			judgmentFlowPath, judgmentFlowRegenerateHint))
	}
	return problems
}

// judgmentFlowTableProblems は決定表と遷移表の形と、ノードの種類ごとの規則を検査する。
func judgmentFlowTableProblems(doc *judgmentFlowDoc) []string {
	var problems []string
	add := func(format string, args ...any) {
		problems = append(problems, judgmentFlowPath+": "+fmt.Sprintf(format, args...))
	}
	if len(doc.Nodes) == 0 {
		add("決定表 (見出しの先頭セルが ID の表) が見つかりません")
	}
	if len(doc.Transitions) == 0 {
		add("遷移表 (見出しの先頭セルが 始点 の表) が見つかりません")
	}
	if len(doc.Nodes) == 0 || len(doc.Transitions) == 0 {
		return problems
	}

	nodes := map[string]judgmentFlowNode{}
	for _, n := range doc.Nodes {
		m := judgmentFlowIDRe.FindStringSubmatch(n.ID)
		if m == nil {
			add("決定表 %d 行目: ID %q はノード ID の形 (D・E・A・H・R と番号) ではありません", n.Line, n.ID)
			continue
		}
		if _, dup := nodes[n.ID]; dup {
			add("%s の行が決定表で重複しています", n.ID)
			continue
		}
		if want := judgmentFlowKindOf[m[1]]; n.Kind != want {
			add("%s の種類が %q です (ID の先頭文字からは %s)", n.ID, n.Kind, want)
		}
		if n.Label == "" {
			add("%s の表示名がありません (決定表の 3 列目。図のノードに出す)", n.ID)
		}
		nodes[n.ID] = n
	}

	outgoing := map[string][]judgmentFlowTransition{}
	seen := map[string]bool{}
	for _, tr := range doc.Transitions {
		ok := true
		if _, exists := nodes[tr.From]; !exists {
			add("遷移表 %d 行目: 始点 %q は決定表にありません", tr.Line, tr.From)
			ok = false
		}
		if _, exists := nodes[tr.To]; !exists {
			add("遷移表 %d 行目: 遷移先 %q は決定表にありません", tr.Line, tr.To)
			ok = false
		}
		if !ok {
			continue
		}
		key := tr.From + "\x00" + tr.Cond + "\x00" + tr.To
		if seen[key] {
			add("遷移表 %d 行目: %s から %s への遷移 (%s) が重複しています", tr.Line, tr.From, tr.To, tr.Cond)
			continue
		}
		seen[key] = true
		outgoing[tr.From] = append(outgoing[tr.From], tr)
	}

	// 種類ごとの規則。保留は人間の判断を待つ状態なので、判断が返ったときの遷移先
	// (判定) が要る。採択・却下は決着なので遷移しない。判定は分岐なので 2 つ以上、
	// 評価は次の 1 つに進む。
	for _, n := range doc.Nodes {
		if _, exists := nodes[n.ID]; !exists {
			continue
		}
		out := outgoing[n.ID]
		switch n.ID[0] {
		case 'H':
			if len(out) == 0 {
				add("保留ノード %s からの遷移がありません (人間の判断が返ったときの遷移先を遷移表に足す)", n.ID)
			}
			for _, tr := range out {
				if !strings.HasPrefix(tr.To, "D") {
					add("保留ノード %s からの遷移先 %s が判定ノードではありません (判断が返ったら判定に戻る)", n.ID, tr.To)
				}
			}
		case 'A', 'R':
			for _, tr := range out {
				add("決着ノード %s から %s への遷移があります (採択・却下は決着なので遷移しない)", n.ID, tr.To)
			}
		case 'D':
			if len(out) < 2 {
				add("判定ノード %s の遷移が %d 本です (判定は 2 つ以上に分かれる)", n.ID, len(out))
			}
		case 'E':
			if len(out) != 1 {
				add("評価ノード %s の遷移が %d 本です (評価は次の 1 つに進む)", n.ID, len(out))
			}
		}
	}

	// 到達可能性。決定表の最初のノードを入口として、辿り着けないノードを報告する。
	// 遷移表に行があっても入口から届かないノードは、判定の途中で使われることがない。
	start := doc.Nodes[0].ID
	reached := map[string]bool{start: true}
	queue := []string{start}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		for _, tr := range outgoing[cur] {
			if !reached[tr.To] {
				reached[tr.To] = true
				queue = append(queue, tr.To)
			}
		}
	}
	for _, n := range doc.Nodes {
		if _, exists := nodes[n.ID]; exists && !reached[n.ID] {
			add("%s に最初のノード %s から到達できません (遷移表に至る遷移が無い)", n.ID, start)
		}
	}
	return problems
}

// writeJudgmentFlowDiagram は判定フローの図を表から生成し、path の最初の mermaid の
// フェンスの中身を置き換えて書き出す (-write-judgment-flow の経路)。表に問題が
// あれば生成しない — 壊れた表から生成した図を正本の隣に置かない。
func writeJudgmentFlowDiagram(path string) error {
	data, err := os.ReadFile(path)
	if err != nil {
		return fmt.Errorf("%s: 判定フローの読み込みに失敗しました: %w", path, err)
	}
	doc := parseJudgmentFlow(data)
	if problems := judgmentFlowTableProblems(&doc); len(problems) > 0 {
		for _, p := range problems {
			fmt.Fprintln(os.Stderr, "  - "+p)
		}
		return fmt.Errorf("%s: 表に %d 件の問題があるので図を生成しません", path, len(problems))
	}
	if !doc.HasDiagram {
		return fmt.Errorf("%s: mermaid のフェンス (```mermaid … ```) がありません。図を置く場所として空のフェンスを 1 つ書く", path)
	}
	rendered := strings.Split(renderJudgmentFlowDiagram(&doc), "\n")
	out := append([]string{}, doc.lines[:doc.DiagramStart+1]...)
	out = append(out, rendered...)
	out = append(out, doc.lines[doc.DiagramEnd:]...)
	if err := os.WriteFile(path, []byte(strings.Join(out, "\n")), 0o644); err != nil {
		return fmt.Errorf("%s: 書き出しに失敗しました: %w", path, err)
	}
	fmt.Printf("生成: %s (図を決定表と遷移表から書き出した)\n", path)
	return nil
}

